import asyncio, json, logging, os, time
from contextlib import AsyncExitStack, asynccontextmanager
from types import SimpleNamespace

import aioboto3
from botocore.config import Config
from fastapi import FastAPI
from pydantic import BaseModel, Field

from .ml import Scorer
from .policy import combine
from .rules import Features, RuleResult, Rules

BUDGET_S = float(os.getenv("BUDGET_MS", "50")) / 1000
MARGIN_S = 0.005
DDB_S = float(os.getenv("DDB_TIMEOUT_MS", "20")) / 1000
TABLE = os.getenv("FEATURE_TABLE", "card_features")
STREAM = os.getenv("KINESIS_STREAM", "payment-events")
log = logging.getLogger("decision")
_DOWN = object()   # DynamoDB failed or timed out (different from "card not found")


class Merchant(BaseModel):
    id: str
    mcc: str
    country: str


class Txn(BaseModel):
    schema_version: str
    transaction_id: str
    event_time: str
    card_token: str
    card_bin: str
    amount_minor: int = Field(gt=0)
    currency: str
    channel: str
    entry_mode: str
    merchant: Merchant
    device_id: str | None = None


class Breaker:
    def __init__(self, max_fails=5, cool_s=2.0):
        self.max, self.cool, self.fails, self.open_until = max_fails, cool_s, 0, 0.0

    def allow(self) -> bool:
        return time.monotonic() >= self.open_until

    def ok(self) -> None:
        self.fails = 0

    def bad(self) -> None:
        self.fails += 1
        if self.fails >= self.max:
            self.open_until, self.fails = time.monotonic() + self.cool, 0


state = SimpleNamespace(
    rules=Rules(os.getenv("RULES_PATH", "config/rules.yaml")),
    scorer=Scorer(os.getenv("MODEL_PATH", "models/model.txt")),
    breaker=Breaker(), q=asyncio.Queue(maxsize=5000), dropped=0, table=None, kinesis=None,
)


async def load_card(token: str):
    if not state.breaker.allow():
        return _DOWN
    try:
        resp = await asyncio.wait_for(
            state.table.get_item(Key={"card_token": token}, ConsistentRead=False), DDB_S)
        state.breaker.ok()
        return resp.get("Item")
    except Exception:
        state.breaker.bad()
        return _DOWN


def build_features(txn: Txn, item) -> Features:
    if item is _DOWN:
        fresh, item = "unavailable", {}
    elif item is None:
        fresh, item = "missing", {}
    else:
        age = time.time() - float(item.get("updated_at", 0))     # epoch seconds
        fresh = "fresh" if age <= state.rules.cfg["stale_after_s"] else "stale"
    avg = float(item.get("avg_amount_30d", 0))                    # major units
    ratio = (txn.amount_minor / 100) / avg if avg > 0 else None
    new_dev = None if not txn.device_id else txn.device_id not in set(item.get("known_devices", []))
    return Features(fresh, int(item.get("txn_count_5m", 0)) + 1, ratio, new_dev,
                    bool(item.get("blocked", False)), txn.amount_minor)


async def pipeline(txn: Txn) -> RuleResult:
    feats = build_features(txn, await load_card(txn.card_token))
    result = state.rules.evaluate(feats)                                   # [7] rules
    score = state.scorer.score(feats, txn)                                 # [8] ML
    return combine(result, score, state.rules.cfg.get("policy", {}))       # [9] policy


def enqueue(record: dict) -> None:
    try:
        state.q.put_nowait(record)
    except asyncio.QueueFull:
        state.dropped += 1


async def sender() -> None:
    while True:
        batch = [await state.q.get()]
        while len(batch) < 100 and not state.q.empty():
            batch.append(state.q.get_nowait())
        try:
            resp = await asyncio.wait_for(state.kinesis.put_records(
                StreamName=STREAM,
                Records=[{"Data": json.dumps(r).encode(), "PartitionKey": r["card_token"]}
                         for r in batch]), 2.0)
            failed = resp.get("FailedRecordCount", 0)   # put_records can partly fail without raising
            if failed:
                state.dropped += failed
                log.warning("kinesis rejected %d records", failed)
        except Exception:
            state.dropped += len(batch)
            log.warning("kinesis send failed; dropped %d", len(batch))


async def reloader() -> None:
    while True:
        await asyncio.sleep(30)
        try:
            state.rules.reload()
        except Exception:
            log.exception("rules reload failed; keeping previous config")


async def warm_up() -> None:
    """Pay one-time client setup costs at startup, not on the first payment."""
    try:
        await asyncio.wait_for(state.table.get_item(Key={"card_token": "warmup"}), 3)
    except Exception:
        pass


@asynccontextmanager
async def lifespan(app: FastAPI):
    cfg = Config(connect_timeout=0.05, read_timeout=0.05, max_pool_connections=200,
                 retries={"max_attempts": 1, "mode": "standard"})        # payment path: strict
    kcfg = Config(connect_timeout=1, read_timeout=2, max_pool_connections=10,
                  retries={"max_attempts": 1, "mode": "standard"})       # background send: relaxed
    async with AsyncExitStack() as stack:
        sess = aioboto3.Session()
        ddb = await stack.enter_async_context(sess.resource("dynamodb", config=cfg))
        state.table = await ddb.Table(TABLE)
        state.kinesis = await stack.enter_async_context(sess.client("kinesis", config=kcfg))
        tasks = [asyncio.create_task(sender()), asyncio.create_task(reloader())]
        await warm_up()
        yield
        for t in tasks:
            t.cancel()


app = FastAPI(lifespan=lifespan)


@app.get("/healthz")
async def healthz():
    return {"ready": state.table is not None, "dropped": state.dropped}


@app.post("/v1/decide")
async def decide(txn: Txn) -> dict:
    t0, fallback = time.monotonic(), False
    try:
        res = await asyncio.wait_for(pipeline(txn), BUDGET_S - MARGIN_S)
    except Exception as exc:
        log.warning("fallback for %s: %r", txn.transaction_id, exc)
        res, fallback = state.rules.fallback(txn.amount_minor), True
    resp = {"transaction_id": txn.transaction_id, "decision": res.decision,
            "reasons": res.reasons, "fallback": fallback,
            "ml_score": res.score, "ml_shadow": res.shadow,
            "latency_ms": round((time.monotonic() - t0) * 1000, 2)}
    enqueue({**resp, "event_id": txn.transaction_id, "card_token": txn.card_token,
             "amount_minor": txn.amount_minor, "event_time": txn.event_time})
    return resp
